def paired_examples(names,ids,judgments):
 rs=[run(n) for n in names];out=[]
 for ident,judgment in zip(ids,judgments):
  rows=[next(c for c in r['cases'] if c['id']==ident) for r in rs];assert len({c['user'] for c in rows})==1
  out.append({'input':ident+' '+rows[0]['user'],'outputs':{r['run_id']:json.dumps(c['assessment']['reply'],ensure_ascii=False) for r,c in zip(rs,rows)},'judgment':judgment})
 return out
